create table if not exists cargo_departures(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),shipping_service_id uuid not null references shipping_services(id),departure_code text not null,scheduled_at timestamptz not null,cutoff_at timestamptz,estimated_arrival_at timestamptz,status text not null default 'OPEN' check(status in ('DRAFT','OPEN','CLOSED','LOADING','DEPARTED','CANCELLED','ARRIVED')),capacity_weight_kg numeric(18,3),capacity_cbm numeric(18,4),reserved_weight_kg numeric(18,3) not null default 0,reserved_cbm numeric(18,4) not null default 0,carrier_name text,transport_reference text,notes text,row_version integer not null default 1,created_by text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(org_id,departure_code));
create table if not exists departure_allocations(id uuid primary key default gen_random_uuid(),org_id text not null references organizations(id),departure_id uuid not null references cargo_departures(id) on delete cascade,shipment_id uuid not null references shipments(id),weight_kg numeric(18,3) not null default 0,volume_cbm numeric(18,4) not null default 0,status text not null default 'RESERVED' check(status in ('RESERVED','LOADED','REMOVED')),idempotency_key text not null,created_by text,created_at timestamptz not null default now(),unique(org_id,idempotency_key),unique(departure_id,shipment_id));
create table if not exists departure_events(id bigserial primary key,org_id text not null references organizations(id),departure_id uuid not null references cargo_departures(id),event_type text not null,actor_id text,actor_name text,payload jsonb not null default '{}',created_at timestamptz not null default now());
create index if not exists idx_departures_calendar on cargo_departures(org_id,scheduled_at,status);create index if not exists idx_departure_allocations on departure_allocations(org_id,departure_id,status);
insert into permissions(permission_code,description) values ('departures.read','Consulter le calendrier des départs'),('departures.manage','Créer et modifier les départs'),('departures.allocate','Réserver la capacité'),('departures.dispatch','Fermer, charger et confirmer le départ'),('departures.cancel','Annuler un départ') on conflict(permission_code) do update set description=excluded.description;
insert into role_permissions(role_id,permission_id) select r.id,p.id from organization_roles r cross join permissions p where (r.role_code in ('OWNER','MANAGER') and p.permission_code like 'departures.%') or (r.role_code in ('OPERATOR','WAREHOUSE') and p.permission_code in ('departures.read','departures.allocate','departures.dispatch')) or (r.role_code in ('SUPPORT','FINANCE') and p.permission_code='departures.read') on conflict do nothing;
